interface Animal {
  name: string;
}
interface Dog extends Animal {
  eat: () => void;
}

type AnimalArray = Array<Animal>;
type DogArray = Array<Dog>;


// DogArray 仍然是 AnimalArray 的子类型，因此 Array<T> 是协变操作
type isChild = DogArray extends AnimalArray ? true : false; // true

type AnimalFn = (param: Animal) => void;
type DogFn = (param: Dog) => void;


// 此时 DogFn 是 AnimalFn 的父类型，父子关系颠倒，因此该变换为逆变
type isChild = DogFn extends AnimalFn ? true : false;  // false
type isParent = AnimalFn extends DogFn ? true : false; // true
